def the_city_heard_of_the_inquiry_and_the_sword(case, data):
    """F4 — Deut 13:13-16 — THE LINE condemned_city_law_declared writing condemned_city_inquiry_required (a STATUS — the seducers' parameters from one noun, Jerusalem excluded, the venue, the seven interrogations with the_inquiries a PARAMETER) and THE CASE'S city_devoted (the sword, the property table, the devoting — Exodus 22:19, Leviticus 27:28-29, Numbers 21:2-3, 7:2 by CALL); the law as a study text (Tosefta Sanhedrin 14:1); Belial (117:3; 1 Kings 21:10)"""
    del P_[:]
    ask = case['ask']
    if ask == 'one_city_at_a_time':
        ink('13:13', '"WHEN YOU HEAR IN ONE OF YOUR CITIES which the LORD your God gives you to dwell there, saying" — the chapter\'s ONE number verse: the parser reads [1] %s (12:14\'s and 17:2\'s the kin %s); "in one of your gates" the four %s; "saying" in the chapter %s' % (NUMS[13], (KINNUM[('Deut', 12, 14)], KINNUM[('Deut', 17, 2)]), P('באחד', 'שעריך'), [v for v in range(1, 20) if 'לאמר' in W13(v)]))
        move('the Sifrei 92:1-4 (read whole at the reading); Sanhedrin 2a, 16b:13-14, 111b:16-19 (read whole at the docket); Mishnah Sanhedrin 1:5 (credited, carried); Tosefta Sanhedrin 14:1; cold_run_place_name (CALL) — PN.the_place_chosen(in_one_of_your_tribes) = %s' % (str(V(PN_ONE))[:60],), "ONE CITY AT A TIME — 'in one of your cities': one, not three (92:3 — two allowed; Tosefta 14:1: R. Shimon bar R. Elazar one or two, R. Shimon one in Judea and one in Galilee, none near the border lest the gentiles break in — 93:3); the court of seventy-one judges the city (Mishnah Sanhedrin 1:5 — Sanhedrin 2a, 16b:13-14: 'you shall take that man or that woman out to your gates' 17:5 — a man and a woman at the local court, not the whole city); A CITY IN TWO TRIBES disputed (111b:16-19); 92:1 the report received, 92:4 in any place; the parser's [1] at 13:13 as at 12:14 (PN by CALL)")
        dat('THE LINE condemned_city_law_declared — STATUTE by form at the counter\'s day %s, NO marker — the chapter\'s last own-day line; the readback row 13:13 SUPPLIED AS A LAW (the first seat — the line\'s own; the [1] by CALL); the parser\'s [1] a DATA row (the_parsers_one — census_probes UNMOVED); the exam\'s person the court that condemns three cities at once — accepted against (92:3)' % (CLOCK['counter'],))
        return out("one city at a time (13:13) — 'in one of your cities' [1] (the parser; 12:14's form by CALL): not three, two allowed (the Sifrei 92:3; Tosefta Sanhedrin 14:1), not the border (93:3), the court of seventy-one (Mishnah Sanhedrin 1:5; Sanhedrin 2a, 16b): THE LINE condemned_city_law_declared at the counter's day; the court that condemns three cities accepted against", ['accepted'])
    if ask == 'to_dwell_there_jerusalem':
        ink('13:13', '"which the LORD your God gives you TO DWELL THERE" — the clause the Torah\'s ONE %s; Jerusalem "not apportioned to a tribe" the run\'s ground' % (P('לשבת', 'שם', books=T),))
        move('the Sifrei 92:5 (read whole at the reading); Bava Kamma 82b:4, 82b:8 (read whole at the docket)', "JERUSALEM CANNOT BECOME A CONDEMNED CITY — THE TEN MATTERS OF JERUSALEM: a house there not irredeemable, no broken-necked heifer, and IT CANNOT BECOME A CONDEMNED CITY (82b:4); the reason 'to dwell there' — Jerusalem was not apportioned to any tribe (82b:8 — the arm of a dispute; the ground from the verse's own clause, 92:5); chapter 12's place outside the ban")
        dat('Jerusalem excluded a DATA row ("to dwell there" the Torah\'s one seat); the exam\'s persons the inhabitants of Jerusalem drawn away — EXEMPT from the city\'s law (judged as individuals by stoning, their property spared — Mishnah 10:4\'s tail)')
        return out("to dwell there — Jerusalem (13:13) — the Torah's one seat of the clause: Jerusalem, not apportioned to a tribe, cannot become a condemned city (Bava Kamma 82b:4, 8 — the Sifrei 92:5): the inhabitants of Jerusalem drawn away exempt from the city's law — judged as individuals", ['exempt'])
    if ask == 'the_seducers_parameters':
        ink('13:14', '"MEN, sons of Belial, HAVE GONE OUT from your midst and have drawn away the inhabitants of THEIR CITY, saying: let us go and serve other gods which you have not known" — "men, sons of Belial, have gone out" the one seat %s; "sons of Belial" the Torah\'s two %s; "have drawn away the inhabitants of their city" %s; THE ONE NARRATIVE VERB in the chapter %s; "you (pl.) knew" against 13:3\'s "you knew them" — the same letters read two ways %s' % (P('יצאו', 'אנשים', 'בני', 'בליעל'), [s for s, _, _ in LEMT('1100', books=T)], P('וידיחו', 'את', 'ישבי', 'עירם'), WAYY, (by[('Deut', 13, 3)][-2], by[('Deut', 13, 14)][-1])))
        move('the Sifrei 93:1-5 (read whole at the reading); Sanhedrin 111b:14, 111b:15, 111b:6-7 (read whole at the docket); Mishnah Sanhedrin 10:4 (read whole here); Sanhedrin 67a:16; cold_run_covenant_at_horeb (CALL) — CH.the_second_word(no_other_gods) = %s' % (str(V(CH_OTHER))[:40],), "THE SEDUCERS' PARAMETERS FROM ONE NOUN AT THEIR BAVLI SEAT — 'are gone out' THEY THEMSELVES, not agents; 'men' NO FEWER THAN TWO, men not women, men not children (111b:14 — 93:1); 'sons of Belial' sons WITHOUT A YOKE; 'from your midst' NOT A BORDER CITY; 'the inhabitants of their city' NOT ANOTHER'S; 'saying' WITNESSES AND FOREWARNING FOR EACH (111b:15 — 93:2-5); the answer sheet: not a condemned city unless its subverters are of that city and tribe, MOST of it subverted, by MEN; women, children, a minority, outsiders — judged as individuals (Mishnah 10:4 at 111b:6); THE STRINGENCY — individuals STONED and their property spared for their heirs, the multitude BY THE SWORD and their property eliminated (111b:7 — the mode-property inverse, city_devoted's ground); the subverter of a multitude among the stoned (Mishnah 7:10's second clause at 67a:16)")
        dat('THE WRITE condemned_city_inquiry_required — a STATUS on israel_people at the counter\'s day (DE2, DE4): the parameters from one noun its value; the readback row 13:14 VARIANT by CALL (the seducers\' one formula — 13:3, 13:7, 13:14 each other\'s closest kin: KINC %s); the seducers\' parameters a DATA row; the exam\'s person the city whose women drew it away — judged as individuals: accepted against (93:1)' % (KINC[14][:1],))
        return out("the seducers' parameters (13:14) — from one noun: themselves not agents, two at least, men not women or children, without a yoke, not the border, their own city, witnesses and forewarning for each (Sanhedrin 111b:14-15 — the Sifrei 93:1-5; Mishnah Sanhedrin 10:4); the stringency — individuals stoned, the multitude by the sword (111b:7): the city drawn away by its women accepted against — judged as individuals", ['condemned_city_inquiry_required'])
    if ask == 'the_majoritys_procedure':
        ink('13:14-16', '"have drawn away THE INHABITANTS of their city … smite, you shall smite the inhabitants of that city" — "the inhabitants of that city" %s; the majority the answer sheet\'s; the inhabitant a datum' % (P('ישבי', 'העיר', 'ההוא'),))
        move('Sanhedrin 112a:2-3, 112a:4-5, 112a:6, 112a:7, 112a:8 (read whole at the docket)', "THE MAJORITY'S PROCEDURE A PARAMETER — how does the court find the majority? imprison each and judge; or stone each until half, then the rest by the sword; or multiply the courts (112a:4-5 — three arms); THE VENUE — 'you shall take that man or that woman out to your gates' (17:5): a man and a woman at the local court, NOT THE WHOLE CITY — the courts multiplied, the verdict by THE GREAT SANHEDRIN (112a:6 — Mishnah 1:5); THE THRESHOLD — caravans that lodged and were subverted: THIRTY DAYS an inhabitant (112a:7 — the sword and their property; less: stoned as individuals, property spared); twelve months a citizen, thirty days an inhabitant — Rava (112a:8); THE SELF-DRAWN CITY — a city that seduced itself: the open dilemma (112a:2-3)")
